const additionalVocabularyKey=word=>[word.en,word.uk].map(value=>String(value).normalize('NFKC').toLowerCase().trim().replace(/\s+/gu,' ')).join('\u0000');
const additionalVocabularyPictures=new Map(additionalVocabularyEntries.map(entry=>[additionalVocabularyKey(entry),entry.pictures]));
const originalLessonIllustrations=lessonIllustrations;
lessonIllustrations=function(word){
  const existing=originalLessonIllustrations(word);
  return existing.length?existing:(additionalVocabularyPictures.get(additionalVocabularyKey(word))||[]);
};
